Detect cycle in directed graph. Topological sort with indegrees.

```python
from collections import deque

def can_finish(n, prereqs):
    graph = {i: [] for i in range(n)}
    indeg = [0] * n
    for a, b in prereqs:
        graph[b].append(a)
        indeg[a] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    visited = 0
    while q:
        u = q.popleft()
        visited += 1
        for v in graph[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return visited == n
```

